"""Compare already registered voting results with immutable single-gate controls; no model calls."""
import gzip,json
from run import ROOT,R,sha,put,anchor_configs,grid_configs
r=json.loads((R/'report.json').read_text());old=anchor_configs();rows=[]
for c in r['configs'].values():
 y=old[c['matched_single_reference']];row={'name':c['name'],'scope':c['scope'],'S':c['trend_lookback_days'] if c['scope']=='native' else c['trend_filter_lookback_days'],'L':c['lookback_days'] if c['scope']=='native' else c['reversal_lookback_days'],'new_status':c['status'],'single_reference':y['name'],'single_original_status':y['status'],'new_full3x_return_pct':c['scenes']['3']['net_return_pct'],'single_full3x_return_pct':y['scenes']['3']['net_return_pct'],'full3x_delta_pp':c['scenes']['3']['net_return_pct']-y['scenes']['3']['net_return_pct'],'new_recent_positive5d1':c['recent40_positive_5d_folds_1x'],'single_recent_positive5d1':y['recent40_positive_5d_folds_1x'],'new_recent3x_return_pct':c['scenes']['3']['recent40']['net_return_pct'],'single_recent3x_return_pct':y['scenes']['3']['recent40']['net_return_pct']}
 if c['scope']=='native':
  a=json.loads(gzip.decompress((ROOT/c['archive']).read_bytes()))['scenes']['1'];b=json.loads(gzip.decompress((ROOT/y['archive']).read_bytes()))['scenes']['1'];assert len(a['decisions'])==len(b['decisions'])==370 and all(x['execution_ts_ns']==z['execution_ts_ns'] for x,z in zip(a['decisions'],b['decisions']));row['actual_1x_decision_directions_different']=sum(x['desired_direction']!=z['desired_direction'] for x,z in zip(a['decisions'],b['decisions']));row['new_1x_fills']=len(a['trades']);row['old_1x_fills']=len(b['trades']);assert row['actual_1x_decision_directions_different']>0
 rows.append(row)
grid=grid_configs(r['configs']);diag={}
for scope in ['native','parent']:
 cs=[c for c in grid.values() if c['scope']==scope];rr=[z for z in rows if z['scope']==scope];diag[scope]={'cells':len(cs),'full3x_net_positive':sum(c['scenes']['3']['net_return_pct']>0 for c in cs),'recent6of8_new':sum(z['new_recent_positive5d1']>=6 for z in rr),'recent6of8_single':sum(z['single_recent_positive5d1']>=6 for z in rr),'full3x_improved_vs_single':sum(z['full3x_delta_pp']>0 for z in rr),'all_parent_recent_fold_counts_identical_to_single':all(z['new_recent_positive5d1']==z['single_recent_positive5d1'] for z in rr) if scope=='parent' else None}
assert len(rows)==12 and diag['parent']['cells']==6 and diag['parent']['recent6of8_new']==2 and diag['parent']['all_parent_recent_fold_counts_identical_to_single']
out={'passed':True,'new_financial_evaluations':0,'report_sha256':sha(R/'report.json'),'source':'Read only completed current/old reports and saved native decisions;no targets,orders,funding or simulation rerun.','by_scope':diag,'rows':rows,'finding':'Majoritychangesactualhistoricaldecisionsandequity,notname-onlyvariation. Someprofitsimprovebutparentrecent6of8qualificationstillonly2of6atS28;neighborsS27/29remain5of8. Presetpassedlabelskept,hypothesisofbroaderrecentqualificationplatformnotconfirmed.','independent_future_profit_established':False};put(R/'majority_diagnostics.json',out)
with (R/'result.md').open('a') as f:f.write('\n关键稳健性结论（仅汇总已完成结果）：'+json.dumps(diag,ensure_ascii=False)+'。多数规则改变了6个原生策略的实际决策与净值，确为新规则。父组合近期正折数与同参数旧单S对照全部相同：仅S28的L3/L4两项达到6/8，S27/S29四邻格仍为5/8；因此“扩大近期资格平台”的假设未获支持。两项按预设门槛保留passed历史标签，但不得把全期收益提升、邻域全期净正或已有历史通过称为消除近期脆弱性或独立前向盈利。\n')
print(json.dumps({'new_financial_evaluations':0,'by_scope':diag,'actual_changed_decisions':{x['name']:x.get('actual_1x_decision_directions_different') for x in rows if x['scope']=='native'}},ensure_ascii=False),flush=True)
